9',NULL,0,'active',NULL,NULL,NULL),(9297,'Conference Board',16,NULL,'a:1:{i:0;s:16:\"Conference Board\";}','Org','The Conference Board, Inc. is a non-profit global business organization supported by business executives that holds conferences, convenes executives and conducts business management research. It holds 501(c)(3) tax-exempt status in the United States. It connects more than 1600 corporations in nearly 60 nations, its worldwide conferences attracting more than 12,000 senior executives each year. These conferences bring together authorities on a wide variety of economic and management issues. More than 150 chief executive officers address Conference Board events each year. Conference Board meetings have been independently rated as one of Americaâs top speaking platforms. The Conference Board also sponsors and manages more than 100 worldwide management councils, attracting senior executives from virtually every business discipline.','Org,IndustryTrade,ThinkTank,ProfessionalAssociation',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(9298,'Heritage Foundation',19,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,NonProfit',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(9299,'William E Simons & Sons',23,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(9300,'Tecumseh Products Co.',21,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(9301,'Saunders Karp & Megrue',22,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(9302,'Forbes Inc.',11,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(9303,'Pittsburgh Tribune-Review Company',33,NULL,'a:1:{i:0;s:33:\"Pittsburgh Tribune-Review Company\";}','Org