ives no funds from general tax revenues. Operations are financed by insurance premiums set by Congress and paid by sponsors of defined benefit plans, investment income, assets from pension plans trusteed by PBGC, and recoveries from the companies formerly responsible for the plans.','Org,GovernmentBody',14682,'2010-10-15 00:00:00','2011-04-07 06:21:59',NULL,0,'active',NULL,NULL,NULL),(10796,'United Steelworkers',19,NULL,'a:1:{i:0;s:20:\"United Steel Workers\";}','Org','','rg,NonProfit,LaborUnion',0,'2010-10-15 00:00:00','2011-04-22 00:33:39',NULL,0,'active',NULL,NULL,NULL),(10797,'eLandia International Inc',25,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(10798,'Forefront Holdings Inc',22,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(10799,'Health Systems Solutions Inc',28,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(10800,'Trump Entertainment',19,NULL,'a:1:{i:0;s:19:\"Trump Entertainment\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(10801,'New York Post',13,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business,MediaOrg',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(10802,'Commercial Club of Chicago',26,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,MembershipOrg',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(10803,'Chicago Museum of Contemporary Art',34,NULL,'a:1:{i:0;s:26:\"Museum of Contemporary Art\";}','Org','','Org,NonProfit,Cultural',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(10804,'National Bank of Commerce',25,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(10805,'Brown Brother