-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(12862,'Koch Agriculture Company',24,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',28220,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(12863,'Matador Cattle Company',22,NULL,'a:1:{i:0;s:0:\"\";}','Org','The Matador Cattle Company, a division of Koch Agriculture Company, operates three ranches: Beaverhead in Montana, Matador in Texas and Spring Creek in Kansas. The ranches total about 425,000 acres and have about 15,000 head of cattle. The Matador Cattle Company is one of the nationâs 10 largest cow/calf operations.','Org,Business',41475,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(12864,'JHMedia',7,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(12865,'Echo Bridge Entertainment',25,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(12866,'United Paramount Network',24,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(12867,'Ion Media Networks',18,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(12868,'UCLA School of Theater, Film, and Television',44,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,School',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(12869,'Academy of Television Arts and Sciences',39,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,NonProfit,Cultural',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(12870,'Hollywood Supports',18,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Philanthropy',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(12871,'University of Tennessee Martin',30,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org',0,'2010