tive',NULL,NULL,NULL),(13369,'New York State Department of Environmental Conservation',55,NULL,'a:1:{i:0;s:44:\"NYS Department of Environmental Conservation\";}','Org','The New York State Department of Environmental Conservation (DEC) was created on July 1,1970 to combine in a single agency all state programs designed to protect and enhance the environment.\r\n\r\nMission: \"To conserve, improve and protect New York\'s natural resources and environment and to prevent, abate and control water, land and air pollution, in order to enhance the health, safety and welfare of the people of the state and their overall economic and social well-being.\"\r\n\r\nDEC\'s goal is to achieve this mission through the simultaneous pursuit of environmental quality, public health, economic prosperity and social well-being, including environmental justice and the empowerment of individuals to participate in environmental decisions that affect their lives.','Org,GovernmentBody',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13370,'National City Bank',18,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13371,'VAnocur LLC',11,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',40792,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13372,'Environmental Systems Design',28,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13373,'Notebaert Nature Museum',23,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Cultural',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13374,'Harris Associates',17,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13375,'Braxner LLC',11,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NUL