,'a:1:{i:0;s:0:\"\";}','Org','As of January 11, 2006, CyberGuard Corp. was acquired by Secure Computing Corp. CyberGuard Corporation provides network security solutions designed to protect enterprises that use the Internet for electronic commerce and secure communication companies worldwide.','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13567,'Mayors Against Illegal Guns Action Fund',39,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13568,'Independence Party of Minnesota',31,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13569,'Trover Solutions Inc',20,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13570,'Democratic Foundation of Orange County',38,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13571,'Bluepac of Pennsylvania (The Blue Cross and Blue Shield Association)',68,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13572,'Gannett Fleming, Inc  PAC',25,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13573,'Puerto Rico Status Resolution Political Action Committee Inc',60,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13574,'American Council of Engineering Companies (Acec/PAC)',52,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13575,'Auto Dealers and Drivers for Free Trade 