LL,0,'active',NULL,NULL,NULL),(13819,'McAfee, Incorporated',20,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13820,'DemandTec',9,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13821,'Hummer Winblad Venture Partners',31,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13822,'Huck PAC',8,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13823,'Salt River Valley Water Users\' Association Political Involvement Committee ( Srppic)',84,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13824,'American Medical Association Political Action Committee',55,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13825,'Ocean County Democratic Committee',33,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13826,'Afl-Cio Cope Political Contributions Committee',46,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13827,'Americans for Honest Politics',29,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13828,'Autism Epidemic Awareness Fund',30,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13829,'Victory America',15,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13830,'Remington Arms Company Inc Political Action Committee (Rempac)',62,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13831,'San Mateo County Democratic Central Committee-Federal',53,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13832,'Alliance To Save Energy',23,NULL,'a:1:{i:0;s:0:\"\";}','Org','Founded in 1977, the Alliance to Save Energy is a non-profit coalition of business, government, environmental and consumer leaders. The Alliance to Save Energy supports energy efficiency as a cost-effective energy resource under existing market conditions and advocates energy-efficiency policies that minimize costs to society and individual consumers, and that lessen greenhouse gas emissions and their impact on the global climate. To carry out its mission, the Alliance to Save Energy undertakes research, educational programs, and policy advocacy, designs and implements energy-efficiency projects, promotes technology development and deployment, and builds public-private partnerships, in the U.S. and other countries.','Org,NonProfit',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13833,'Rocky Mountain Institute',24,NULL,'a:1:{i:0;s:0:\"\";}','Org','We envisage a world thriving, verdant, and secure, for all, for ever. To that end, our mission is to drive the efficient and restorative use of resources.\r\n\r\nRMI\'s style is nonadversarial and transideological, emphasizing integrative design, advanced technologies, and mindful markets.\r\n\r\nWe work extensively with the private sector, as well as with civil society and government, to create abundance by design and to apply the framework of Natural Capitalism.','Org,NonProfit,PrivateCompany,ThinkTank',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13834,'Citicorp Voluntary Political Fund Federal',41,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13835,'Central Park Conservancy',24,NULL,'a:1:{i:0;s:0:\"\";}','Org','The Central Park Conservancy is a private, not-for-profit organization founded in 1980 that manages Central Park under a contract with the New York City Department of Parks & Recreation. Thanks to the generosity of many individuals, corporations, foundations, and the City of New York, the Conservancy has invested more than $500 million to date into the Park making it a model for urban parks worldwide. The Conservancy provides 85% of Central Park\'s $27 million annual operating budget and is responsible for all basic care of the Park.\r\n\r\nWith 25 million visitors each year to its 843 acres, Central Park is the most frequently visited urban park in the United States.  To manage the Park, Conservancy crews aerate and seed lawns; rake leaves; prune and fertilize trees; plant shrubs and flowers; maintain ballfields and playgrounds; remove graffiti; conserve monuments, bridges, and buildings; and care for waterbodies and woodlands, controlling erosion, maintaining the drainage system, and protecting over 150 acres of lakes and streams from pollution, siltation, and algae.','Org,NonProfit,PrivateCompany',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13836,'Ralph Lauren Center for Cancer Care and Prevention',50,NULL,'a:1:{i:0;s:0:\"\";}','Org','The Ralph Lauren Center for Cancer Care and Prevention is a community based Center for the prevention, diagnosis and treatment of cancer through new models of patient care, research, education and outreach designed to address the unique needs of the community. \r\nLocated in East Harlem, New York, just one block from historic 125th Street, the Center features a warm, friendly environment where guests can count on personalized attention. Assisted by Polo Ralph Lauren designers, the space was created to inspire serenity and comfort. The Center features art representative of the African American and Latino experience.','Org,Philanthropy',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13837,'Ascenta Therapeutics, Inc',25,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13838,'Raven Biotechnologies, Inc',26,NULL,'a:1:{i:0;s:0:\"\";}','Org','Raven biotechnologies, Inc., a biotechnology company, focuses on the development of monoclonal antibody therapeutics for treating cancer. Its lead product candidate, RAV12, targets adenocarcinomas and used for the treatment of gastrointestinal, lung, colon, pancreatic, prostate, breast, brain, and ovarian cancer. The company was founded in 1999 and is based in South San Francisco, California. As of July 17, 2008, Raven Biotechnologies, Inc. operates as a subsidiary of MacroGenics, Inc.','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13839,'Seattle Genetics',16,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13840,'Alfred P. Sloan Foundation',26,NULL,'a:1:{i:0;s:0:\"\";}','Org','Alfred P. Sloan was elected President of General Motors in 1923, succeeding Pierre S. du Pont.  The foundation he founded in 1934 now makes grants primarily to support original research and broad-based education related to science, technology, economic performance and the quality of American life. \r\nThe Foundation is unique in its focus on science, technology, and economic institutionsâand the scholars and practitioners who work in these fieldsâas chief drivers of the nationâs health and prosperity. The Foundation has a deep-rooted belief that carefully reasoned systematic understanding of the forces of nature and society, when applied inventively and wisely, can lead to a better world for all.','Org,Philanthropy',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13841,'Picower Foundation',18,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13842,'Coleman Victory Cmte- Non Federal Acct',38,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13843,'Minnesota Bankers Political Action Committee',44,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13844,'H H H Fund a Committee for Responsible Leadership; the',54,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13845,'Softer Voices',13,NULL,'a:1:{i:0;s:0:\"\";}','Org','Softer Voices (\"SV\") is a conservative issue advocacy organization comprising a diverse coalition of concerned citizens who wish to promote public policies that maintain and improve the lives of every American. SV is particularly concerned with national security issues, as well as issues which affect our economy and free markets, the success and viability of our nation\'s families, and the culture necessary for a free and democratic society.\r\n\r\nThe goals of the SV media campaign are: to be an effective voice to speak to women on issues of national concern; and to support policies that enhance America\'s security and liberty. \r\n\r\nSofter Voices is a 527 political committee. It will purchase advertisements and maintain a web site designed to enhance the knowledge of the general public on issues of importance to the organization. SV will also pursue its goals through a combination of earned media outreach, local press conferences, and op-eds.\r\n\r\n(The most recent TV ad on the group\'s web page is in support of former Pennsylvania Senator Rick Santorum)','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13846,'Ed XL PAC',9,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13847,'America Women Vote! 2002',24,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13848,'Mirant Corporation PAC, Inc.',28,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13849,'Capitol Club Political Action Committee',39,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13850,'Targetcitizens Political Forum',30,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13851,'Starr Foundation',16,NULL,'a:1:{i:0;s:0:\"\";}','Org','The Starr Foundation was established in 1955 by Cornelius Vander Starr, an insurance entrepreneur who founded C.V. Starr & Co. and other companies later combined by his successor, Maurice R. Greenberg into what became the American International Group, Inc. Mr. Starr, a pioneer of globalization, set up his first insurance venture in Shanghai in 1919. He died in 1968 at the age of 76, leaving his estate to the Foundation. \r\n\r\nThe Foundation currently has assets of approximately $1.25 billion, making it one of the largest private foundations in the United States. It makes grants in a number of areas, including education, medicine and healthcare, human needs, public policy, culture and the environment.','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(13852,'Southern Company Employees PAC',30,NULL,'a:1:{i:0;s:0:\"\";}','Or