y the state legislature or governor Prop. 71, which amended the state constitution.','Org,GovernmentBody',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14573,'Novocell, Inc.',14,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14574,'NetJets',7,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14575,'MidAmerican Energy Holdings Company',35,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Business',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14576,'Midamerican Energy Company Executive PAC',40,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14577,'Midamerican Energy Company Effective Government Committee',57,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14578,'Kentucky Pro-Life Political Action Committee',44,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14579,'US DOJ Office of Juvenile Justice and Delinquency Prevention',60,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14580,'J. R. Simplot Company Political Action Committee',48,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14581,'Citi Foundation',15,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14582,'Allen & Overy',13,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,LawFirm',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14583,'The Clearing Corporation',2