rs Foundation provides expertise, resources, best practices and a network to companies so that maximum corporate and community benefit is achieved.','Org,Philanthropy',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14802,'Svb Financial Group Political Action Committee',46,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14803,'Pasteur Foundation',18,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,Philanthropy',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14804,'Foreign Policy Association',26,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,NonProfit',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14805,'Institute of International Education',36,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,NonProfit',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14806,'Andrew Cuomo 2010',17,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14807,'University of Puget Sound',25,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,School',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14808,'Tobacco Institute Political Action Committee',44,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14809,'UNITE HERE Local 6',18,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,LaborUnion',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14810,'Local 6 Committee on Public Education',37,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,PoliticalFundraising',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NULL),(14811,'Berger & Montague',17,NULL,'a:1:{i:0;s:0:\"\";}','Org','','Org,LawFirm',0,'2010-10-15 00:00:00','2011-03-16 01:28:49',NULL,0,'active',NULL,NULL,NUL